import {analyze,parseData,number,scenarioData,SCENARIOS,CONSTANTS,mean} from './engine.js';
const icons={chart:'<path d="M3 3v18h18"/><path d="m6 15 4-6 4 4 6-8"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',data:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',book:'<path d="M12 5c-3-2-7-2-10-1v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1v15"/>',exercise:'<path d="m4 13 6 6L21 5"/><path d="M20 13v7H3V3h12"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',alert:'<path d="M10 4 2 18a1.4 1.4 0 0 0 1 2h18a1.4 1.4 0 0 0 1-2L14 4a2.3 2.3 0 0 0-4 0Z"/><path d="M12 9v4m0 3v.1"/>',wave:'<path d="M2 12h3l3-7 5 14 4-10 2 3h3"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',bulb:'<path d="M9 18h6m-5 3h4M8 14a6 6 0 1 1 8 0l-1 2H9Z"/>',sliders:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="white"/><circle cx="16" cy="12" r="2" fill="white"/><circle cx="9" cy="18" r="2" fill="white"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z"/><path d="m8 11 3 3 5-6"/>'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg>`;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=3)=>v===null||!Number.isFinite(v)?'—':v.toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const base=scenarioData();
let state={scenario:'stable',custom:false,mode:'xbar',n:5,raw:base.text,process:base.scenario.process,unit:'mm',lsl:49.9,usl:50.1,target:50,minCpk:1.33,rules:['r1','r2','r3'],assumptions:{msa:false,rational:false,normal:false},done:{},exercise:0};
try{const saved=JSON.parse(localStorage.getItem('spc-lab-v1'));if(saved&&typeof saved==='object'){const merged={...state,...saved};const g=parseData(merged.raw,merged.mode,merged.n,merged.delimiter||'auto');analyze(g,merged);state=merged;}}catch{}
let result;const calculate=()=>{result=analyze(parseData(state.raw,state.mode,state.n,state.delimiter||'auto'),state);};calculate();
let view=['process','data','capability','exercises','guide'].includes(location.hash.slice(1))?location.hash.slice(1):'process';
let chartTab='primary',chartWindow=50,selectedPoint=null,feedback=null,hint=false,formError='',mobile=false,exerciseAnswer='';
const routes=[{id:'process',name:'Visão do processo',icon:'grid'},{id:'data',name:'Dados & coleta',icon:'data'},{id:'capability',name:'Capacidade',icon:'target'},{id:'exercises',name:'Exercícios práticos',icon:'exercise'},{id:'guide',name:'Guia de decisão',icon:'book'}];
function save(){try{localStorage.setItem('spc-lab-v1',JSON.stringify(state));}catch{toast('O navegador não permitiu salvar. Exporte um backup para preservar sua análise.');}}
let toastTimer;function toast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
function navigate(v){if(!routes.some(x=>x.id===v))v='process';view=v;history.replaceState(null,'','#'+v);mobile=false;formError='';render();window.scrollTo(0,0);document.querySelector('h1')?.focus({preventScroll:true});}
function loadScenario(id,mode=state.mode,n=state.n){const d=scenarioData(id,mode,n);Object.assign(state,{scenario:d.scenario.id,custom:false,mode,n,raw:d.text,process:d.scenario.process,unit:d.scenario.unit,lsl:d.scenario.lsl,usl:d.scenario.usl,target:d.scenario.target,delimiter:'auto',assumptions:{msa:false,rational:false,normal:false}});calculate();save();selectedPoint=null;chartTab='primary';formError='';render();toast('Cenário carregado. Dados sintéticos para treinamento.');}
const scenario=()=>SCENARIOS.find(s=>s.id===state.scenario)||SCENARIOS[0];
function status(){return result.zero?{title:'Variação não estimável',short:'Revisar medição',class:'warn',text:'A amplitude média é zero. Verifique resolução, arredondamento e repetição dos valores; os índices não podem ser estimados.'}:result.events.length?{title:'Investigue o comportamento',short:'Sinais especiais',class:'bad',text:`Detectamos ${result.events.length} ocorrência(s) de regras. Investigue as causas antes de usar os índices para concluir capacidade.`}:result.short?{title:'Amplie a base de análise',short:'Base preliminar',class:'warn',text:'Nenhum sinal nas regras selecionadas, mas a base tem menos de 20 pontos ou subgrupos. Colete mais dados em condições representativas.'}:{title:'Consistência é um bom sinal.',short:'Sem sinais',class:'good',text:'Nenhum sinal nas regras selecionadas, nas cartas de localização e dispersão. A estabilidade é provisória e depende da coleta e da medição.'};}
function shell(content){const done=Object.keys(state.done).filter(k=>state.done[k]).length;return`<div class="app-shell ${mobile?'menu-open':''}"><button class="nav-overlay" data-action="menu" aria-label="Fechar menu"></button><aside class="sidebar"><a class="brand" href="#process" data-route="process"><div class="brand-mark">${icon('wave')}</div><div><div class="brand-name">SPC <span>Lab</span></div><div class="brand-sub">CORE TOOLS / DEKO</div></div></a><div class="nav-label">SEU LABORATÓRIO</div><nav class="nav" aria-label="Navegação principal">${routes.map(r=>`<a href="#${r.id}" data-route="${r.id}" class="${view===r.id?'active':''}" ${view===r.id?'aria-current="page"':''}>${icon(r.icon)}<span>${r.name}</span>${r.id==='exercises'?`<span class="nav-badge">${done}/6</span>`:''}</a>`).join('')}</nav><div class="side-bottom"><div class="course-card"><div class="eyebrow">APRENDER FAZENDO</div><strong>Da teoria ao chão de fábrica.</strong><p>Pratique decisões, entenda os sinais e transforme dados em evidências.</p><div class="progress-track" role="progressbar" aria-label="Exercícios concluídos" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="6"><span style="width:${done/6*100}%"></span></div><a href="#exercises" data-route="exercises"><span>${done} de 6 desafios concluídos</span><span>↗</span></a></div><div class="profile"><div class="avatar">D</div><div>Deko<small>Seu espaço de qualidade</small></div><span class="private-dot"></span></div></div></aside><div class="workspace"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Abrir menu" aria-expanded="${mobile}">${icon('menu')}</button><div class="breadcrumb"><span>Core Tools</span><span class="chevron">/</span><span>Laboratório SPC</span><span>/</span><strong>${routes.find(r=>r.id===view).name}</strong></div><div class="top-actions"><span class="private">${icon('lock')} Ambiente privado</span><button class="btn" data-action="report">${icon('download')} Exportar análise</button></div></header><main class="main" id="main">${content}<footer class="footer"><span>SPC Lab · Aprendizado aplicado à indústria <span aria-hidden="true">&nbsp; / &nbsp;</span> <a href="#guide" data-route="guide">Métodos e referências ↗</a></span><span>Core Tools · AIAG & VDA SPC<br>Ambiente autoral independente</span></footer></main></div></div>`;}
function hero(eyebrow,title,sub,note=''){return`<section class="hero"><div><div class="eyebrow">${eyebrow}</div><h1 tabindex="-1">${title}</h1><p>${sub}</p></div>${note?`<div class="hero-note">${icon('shield')}<div><strong>Primeiro, entenda o processo.</strong>${note}</div></div>`:''}</section>`;}
function toolbar(){return`<section class="scenario-bar" aria-label="Configuração rápida"><div class="scenario-label">${icon('sliders')} CENÁRIO</div><div class="select-wrap"><label class="visually-hidden" for="scenario">Cenário de processo</label><select id="scenario">${state.custom?'<option value="custom">Minha base de processo</option>':''}${SCENARIOS.map(s=>`<option value="${s.id}" ${!state.custom&&state.scenario===s.id?'selected':''}>${s.name}</option>`).join('')}</select></div><span class="synthetic-tag">${state.custom?'Base inserida':'Dados sintéticos'}</span><div class="type-select"><label class="visually-hidden" for="quickMode">Tipo de carta</label><select id="quickMode"><option value="xbar" ${state.mode==='xbar'?'selected':''}>X̄–R · n = ${state.n}</option><option value="imr" ${state.mode==='imr'?'selected':''}>I–MR · Individuais</option></select></div><a class="btn small" href="#data" data-route="data">${icon('data')} Editar dados</a></section>`;}
function kpis(){const st=status();return`<div class="kpis"><article class="kpi"><div class="kpi-label">Média do processo ${icon('wave')}</div><div class="kpi-value">${fmt(result.mean,4)}<small>${escape(state.unit)}</small></div><div class="kpi-bottom">${result.count} medições · ${result.points} ${state.mode==='imr'?'pontos':'subgrupos'}</div></article><article class="kpi"><div class="kpi-label">Desvio dentro · σ̂ ${icon('chart')}</div><div class="kpi-value">${fmt(result.within,4)}<small>${escape(state.unit)}</small></div><div class="kpi-bottom">${state.mode==='imr'?'MR̄ / 1,128':'R̄ / d₂'} · variação de curto prazo</div></article><article class="kpi feature"><div class="kpi-label">Índice de capacidade · Cpk ${icon('target')}</div><div class="kpi-value">${fmt(result.cpk,2)}<small>meta ≥ ${fmt(state.minCpk,2)}</small></div><div class="kpi-bottom"><span class="dot"></span>${result.events.length?'Exploratório · há sinais especiais':'Estimativa condicionada às premissas'}</div></article><article class="kpi"><div class="kpi-label">Comportamento do processo ${icon('shield')}</div><div class="kpi-status ${st.class}">${st.short}</div><div class="kpi-bottom">${result.events.length?`${result.events.length} ocorrências · investigar`:result.zero?'Verificar resolução da medição':`${state.rules.length} regras ativas · localização + dispersão`}</div></article></div>`;}
function controlChart(){const primary=chartTab==='primary';const vals=primary?result.primary:result.secondary;const limits=primary?result.limits:result.rangeLimits;const offset=state.mode==='imr'&&!primary?1:0;
 const start=Math.max(0,vals.length-(chartWindow||vals.length)),v=vals.slice(start);let lo=Math.min(...v,limits.lcl),hi=Math.max(...v,limits.ucl);const span=hi-lo||Math.max(Math.abs(hi)*.001,.01);lo-=span*.22;hi+=span*.25;if(!primary)lo=Math.max(0,lo);
 const w=820,h=245,p={l:64,r:82,t:24,b:32},pw=w-p.l-p.r,ph=h-p.t-p.b;const X=i=>p.l+(v.length===1?pw/2:i/(v.length-1)*pw),Y=x=>p.t+(hi-x)/(hi-lo)*ph;
 const affected=new Set();result.events.filter(e=>e.chart===(primary?(state.mode==='imr'?'I':'X̄'):(state.mode==='imr'?'MR':'R'))).forEach(e=>{for(let i=e.start;i<=e.end;i++)affected.add(i);});
 const ticks=Array.from({length:5},(_,i)=>lo+(hi-lo)*i/4);
 return`<svg class="control-chart" viewBox="0 0 ${w} ${h}" role="group" aria-label="${primary?(state.mode==='imr'?'Carta de valores individuais':'Carta de médias dos subgrupos'):'Carta de amplitudes'}; clique em um ponto para inspecionar"><title>${primary?'Localização do processo':'Dispersão do processo'}</title>${ticks.map(t=>`<line x1="${p.l}" x2="${w-p.r}" y1="${Y(t)}" y2="${Y(t)}" stroke="#edf0e7"/><text x="${p.l-12}" y="${Y(t)+3}" text-anchor="end">${fmt(t,3)}</text>`).join('')}${[['ucl','LSC'],['cl','LC'],['lcl','LIC']].map(([key,label])=>`<line x1="${p.l}" x2="${w-p.r+5}" y1="${Y(limits[key])}" y2="${Y(limits[key])}" stroke="${key==='cl'?'#a6bc8d':'#c89984'}" stroke-dasharray="${key==='cl'?'3 5':'5 5'}"/><text class="limit-label" x="${w-p.r+13}" y="${Y(limits[key])+3}" style="${key==='cl'?'fill:#81976b':''}">${label} ${fmt(limits[key],3)}</text>`).join('')}<path d="${v.map((x,i)=>`${i?'L':'M'}${X(i).toFixed(2)},${Y(x).toFixed(2)}`).join(' ')}" stroke="#568a79" stroke-width="1.6" fill="none"/>${v.map((x,i)=>{const idx=start+i+offset,red=affected.has(idx);return`<circle class="point" cx="${X(i)}" cy="${Y(x)}" r="${selectedPoint===idx?5:3.1}" fill="${red?'#c27556':'#568a79'}" stroke="white" stroke-width="1.4" role="button" tabindex="0" data-point="${idx}" aria-label="${primary?'Ponto':'Amplitude'} ${idx+1}: ${fmt(x,4)}${red?', sinal detectado':''}"><title>${primary?(state.mode==='xbar'?'Subgrupo':'Ponto'):'Amplitude'} ${idx+1} · ${fmt(x,4)} ${escape(state.unit)}${red?' · Sinal detectado':''}</title></circle>`;}).join('')}${v.map((x,i)=>(i===0||i===v.length-1||(i+start+offset+1)%5===0)&&v.length<=100?`<text x="${X(i)}" y="${h-10}" text-anchor="middle">${start+i+offset+1}</text>`:'').join('')}${v.length>100?`<text x="${p.l}" y="${h-10}">${start+offset+1}</text><text x="${w-p.r}" y="${h-10}" text-anchor="end">${vals.length+offset}</text>`:''}</svg>`;
}
function pointDetail(){if(selectedPoint===null||!result.groups[selectedPoint])return'';const g=result.groups[selectedPoint];return`<div class="point-detail"><strong>${state.mode==='xbar'?'Subgrupo':'Ponto'} ${selectedPoint+1}</strong><span>${g.map(x=>fmt(x,4)).join(' · ')} ${escape(state.unit)}</span><button class="btn ghost small" style="margin-left:auto;padding:0" data-action="clearPoint" aria-label="Fechar detalhe do ponto">${icon('close')}</button></div>`;}
function processPage(){const st=status();return hero('LABORATÓRIO DE PROCESSO','Do dado à <em>decisão.</em>','Explore a variação, reconheça sinais e decida com evidência. O seu próximo passo começa no comportamento do processo.','Depois, avalie a capacidade.')+toolbar()+kpis()+`<div class="lab-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Carta de controle ${state.mode==='imr'?'I–MR':'X̄–R'}</h2><p class="panel-sub">${escape(state.process)} · ${escape(state.unit)}</p></div><div class="chart-tabs" role="tablist" aria-label="Carta exibida"><button role="tab" aria-selected="${chartTab==='primary'}" data-tab="primary" class="${chartTab==='primary'?'active':''}">${state.mode==='imr'?'Individual':'Médias X̄'}</button><button role="tab" aria-selected="${chartTab==='secondary'}" data-tab="secondary" class="${chartTab==='secondary'?'active':''}">${state.mode==='imr'?'Amplitude MR':'Amplitude R'}</button></div></div><div class="chart-meta"><div class="legend"><span><i></i>${chartTab==='primary'?'Processo':'Amplitude'}</span><span><i class="center"></i>Centro</span><span><i class="dashed"></i>Limites de controle</span></div><label>Exibir <select class="mini-select" id="chartWindow" aria-label="Quantidade de pontos visíveis"><option value="50" ${chartWindow===50?'selected':''}>50 pontos</option><option value="100" ${chartWindow===100?'selected':''}>100 pontos</option><option value="0" ${chartWindow===0?'selected':''}>Todos</option></select></label></div><div class="chart-area">${controlChart()}</div>${pointDetail()}<div class="chart-foot">${icon('info')} Fase I · Limites estimados com a base atual. Todos os dados entram nos cálculos. Clique nos pontos para explorar.</div></section><aside class="panel interpret"><div class="eyebrow">LEITURA DO PROCESSO</div><div class="status-icon ${st.class==='good'?'':'alert'}">${icon(st.class==='good'?'check':'alert')}</div><h2>${st.title}</h2><p>${st.text}</p><div class="next-action"><strong>Seu próximo passo</strong><p>${result.events.length?'Investigue a causa, proteja o produto e registre a reação. Reestime limites apenas após justificar as mudanças.':result.zero?'Verifique resolução, método e sistema de medição. Recolete dados com variação mensurável.':result.short?'Amplie a amostragem antes de estabelecer limites de referência para o monitoramento.':'Compare a variação com a tolerância e confirme as premissas de capacidade.'}</p><a class="btn ${result.events.length?'':'primary'} small" href="#${result.events.length?'guide':'capability'}" data-route="${result.events.length?'guide':'capability'}">${result.events.length?'Ver plano de reação':'Analisar capacidade'} ${icon('arrow')}</a></div></aside></div><div class="bottom-grid"><section class="panel signals-panel"><div class="section-row"><h2 class="panel-title">Sinais para investigar</h2><span class="pill ${result.events.length?'red':result.zero||result.short?'amber':''}">${result.events.length?`${result.events.length} ocorrências`:'Nenhum sinal detectado'}</span></div>${result.events.length?`<div class="signal-list">${result.events.map(e=>`<div class="signal-item"><div><strong>${e.chart}</strong> · ${e.text}</div><button data-event-point="${e.end}" data-event-chart="${e.chart}">${e.start===e.end?`Ponto ${e.end+1}`:`${e.start+1}–${e.end+1}`} ↗</button></div>`).join('')}</div>`:`<div class="empty-signals">${icon('check')} ${result.zero?'Limites degenerados: não é possível concluir estabilidade.':'A leitura inclui localização e dispersão. Continue monitorando o processo.'}</div>`}<div class="rule-strip">${state.rules.map(r=>`<span><span class="tick">✓</span> ${{r1:'Além de 3σ',r2:'9 do mesmo lado',r3:'6 em tendência',r4:'2 de 3 além de 2σ',r5:'4 de 5 além de 1σ'}[r]}</span>`).join('')}<a href="#data" data-route="data">Configurar regras ↗</a></div></section><aside class="tip-card"><div class="eyebrow">${icon('bulb')} INSIGHT DE CORE TOOLS</div><h3>Controle ≠ especificação.</h3><p>Limites de controle vêm do processo. Limites de especificação vêm do requisito. Um processo pode ser estável e ainda não atender ao cliente.</p></aside></div>`;}
function dataPage(){return hero('DADOS & COLETA','Seu processo. <em>Seus dados.</em>','Use um cenário industrial ou traga medições em ordem de coleta. Uma boa análise começa com uma boa amostragem.')+toolbar()+`<div class="two-col"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Configurar a análise</h2><p class="panel-sub">Especificação bilateral · variáveis contínuas</p></div><span class="pill">${result.count} leituras na base atual</span></div><form id="dataForm" class="panel-body">${formError?`<div class="notice error" role="alert">${escape(formError)}</div>`:''}<div class="form-grid"><div class="field full"><label for="processName">Processo / característica</label><input id="processName" name="process" maxlength="120" required value="${escape(state.process)}"></div><div class="field"><label for="draftMode">Carta de controle</label><select id="draftMode" name="mode"><option value="xbar" ${state.mode==='xbar'?'selected':''}>X̄–R · subgrupos</option><option value="imr" ${state.mode==='imr'?'selected':''}>I–MR · individuais</option></select></div><div class="field"><label for="groupN">Peças por subgrupo</label><select id="groupN" name="n">${Object.keys(CONSTANTS).map(n=>`<option value="${n}" ${+n===state.n?'selected':''}>${n} peças</option>`).join('')}</select><small>Usado apenas em X̄–R</small></div><div class="field"><label for="unit">Unidade</label><input id="unit" name="unit" maxlength="15" value="${escape(state.unit)}" required></div><div class="field"><label for="lsl">Limite inferior · LI</label><input id="lsl" name="lsl" inputmode="decimal" required value="${fmt(state.lsl,4)}"></div><div class="field"><label for="target">Alvo</label><input id="target" name="target" inputmode="decimal" required value="${fmt(state.target,4)}"></div><div class="field"><label for="usl">Limite superior · LS</label><input id="usl" name="usl" inputmode="decimal" required value="${fmt(state.usl,4)}"></div><div class="field"><label for="minCpk">Meta didática de Cpk</label><input id="minCpk" name="minCpk" inputmode="decimal" required value="${fmt(state.minCpk,2)}"><small>Confirme o requisito do cliente.</small></div><div class="field"><label for="delimiter">Separador dos dados</label><select id="delimiter" name="delimiter">${[['auto','Automático'],['semicolon','Ponto e vírgula ;'],['comma','Vírgula ,'],['tab','Tabulação'],['line','Um valor por linha']].map(([v,l])=>`<option value="${v}" ${(state.delimiter||'auto')===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field full"><label for="rawData">Medições em ordem cronológica</label><textarea id="rawData" name="raw" class="data-text" spellcheck="false" required>${escape(state.raw)}</textarea><small>X̄–R: uma linha por subgrupo, exatamente n valores. I–MR: um valor por linha ou lista separada. Até 2.000 medições.</small></div></div><div class="section-row mt"><h3 class="panel-title">Regras de sinalização</h3><a class="text-link" href="#guide" data-route="guide">Como interpretar</a></div><div class="checklist">${[['r1','1 ponto além de 3σ','Sempre aplicada à carta de amplitude, mesmo se desmarcada aqui.'],['r2','9 pontos consecutivos do mesmo lado da média','Igualdade com a média interrompe a sequência.'],['r3','6 pontos consecutivos crescentes ou decrescentes','Valores empatados interrompem a tendência.'],['r4','2 de 3 pontos além de 2σ, no mesmo lado','Regra de zona opcional.'],['r5','4 de 5 pontos além de 1σ, no mesmo lado','Regra de zona opcional.']].map(([r,t,h])=>`<label><input type="checkbox" name="rules" value="${r}" ${state.rules.includes(r)?'checked':''}><span>${t}<small>${h}</small></span></label>`).join('')}</div><p class="help-text">As regras de sequência e zona se aplicam apenas à carta de localização (I ou X̄). São um conjunto didático configurável; usar mais regras aumenta o risco de alarmes falsos.</p><div class="form-actions"><button class="btn primary" type="submit">Calcular e visualizar ${icon('arrow')}</button><button class="btn" type="button" data-action="csv">${icon('download')} Baixar CSV</button><button class="btn ghost" type="button" data-action="backup">Salvar backup</button></div></form></section><aside><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Trazer uma base de processo</h2><p class="panel-sub">Sem envio das medições a um servidor</p></div></div><div class="panel-body"><label class="upload" for="fileInput">${icon('upload')} Escolher arquivo CSV, TXT ou backup JSON<small>Até 1 MB · revise os dados antes de calcular</small></label><input type="file" id="fileInput" class="visually-hidden" accept=".csv,.txt,.json,text/csv,text/plain,application/json"><p class="help-text">Aceita ponto decimal. Para vírgula decimal, use ponto e vírgula ou tabulação entre as medições. Exemplo:</p><div class="formula">50,012;49,985;50,021;50,003;49,992</div><p class="help-text">Cabeçalhos opcionais: x1;x2;… ou valor. Não inclua número de peça, data ou horário como uma medição.</p><div class="notice">A importação preenche o editor. Clique em <strong>Calcular e visualizar</strong> para aplicar os dados.</div></div></section><section class="panel mt"><div class="panel-head"><h2 class="panel-title">Antes de medir</h2></div><div class="panel-body"><ol class="steps"><li><div><strong>Confirme o requisito</strong>Desenho, revisão, tolerância e característica.</div></li><li><div><strong>Verifique a medição</strong>MSA, resolução e rastreabilidade adequadas.</div></li><li><div><strong>Defina subgrupos racionais</strong>Peças em condições próximas dentro do grupo; variações de tempo entre grupos.</div></li><li><div><strong>Preserve a sequência</strong>Não ordene pelos valores. Registre setup, turno, lote e ferramenta.</div></li></ol><p class="help-text">O conteúdo disponível do seu Core Tools Lab orienta este ambiente. O material integral do curso não foi disponibilizado; os exercícios são autorais.</p></div></section></aside></div>`;}
function histogram(){const a=result.all;let low=Math.min(...a,state.lsl),high=Math.max(...a,state.usl);const pad=(high-low)*.1||.1;low-=pad;high+=pad;const bins=14,bw=(high-low)/bins,counts=Array(bins).fill(0);a.forEach(v=>counts[Math.min(bins-1,Math.max(0,Math.floor((v-low)/bw)))]++);const max=Math.max(...counts,1)*1.15,w=670,h=260,p={l:38,r:22,t:31,b:38},pw=w-p.l-p.r,ph=h-p.t-p.b,X=x=>p.l+(x-low)/(high-low)*pw,Y=y=>p.t+(1-y/max)*ph;
 return`<svg class="histogram" viewBox="0 0 ${w} ${h}" role="img" aria-label="Histograma das medições individuais comparado aos limites de especificação"><title>Histograma: medições, alvo e especificação</title>${Array.from({length:4},(_,i)=>`<line x1="${p.l}" x2="${w-p.r}" y1="${Y(i*max/3)}" y2="${Y(i*max/3)}" stroke="#edf1e5"/><text x="${p.l-8}" y="${Y(i*max/3)+3}" text-anchor="end">${Math.round(i*max/3)}</text>`).join('')}${counts.map((c,i)=>`<rect x="${X(low+i*bw)+2}" y="${Y(c)}" width="${pw/bins-4}" height="${Y(0)-Y(c)}" fill="#a9c79c" rx="3"><title>${fmt(low+i*bw,4)} a ${fmt(low+(i+1)*bw,4)}: ${c} medições</title></rect>`).join('')}${[['LI',state.lsl],['ALVO',state.target],['LS',state.usl]].map(([label,v])=>`<line x1="${X(v)}" x2="${X(v)}" y1="${p.t-8}" y2="${Y(0)}" stroke="${label==='ALVO'?'#719552':'#be8b73'}" stroke-dasharray="4 4"/><text x="${X(v)}" y="${p.t-17}" text-anchor="middle" style="fill:${label==='ALVO'?'#719552':'#ad7e66'}">${label}</text>`).join('')}${Array.from({length:6},(_,i)=>low+(high-low)*i/5).map(x=>`<text x="${X(x)}" y="${h-15}" text-anchor="middle">${fmt(x,3)}</text>`).join('')}<text x="${w-p.r}" y="${h-1}" text-anchor="end">${escape(state.unit)} · frequência observada</text></svg>`;}
function capabilityPage(){const st=status(),ready=result.stable&&Object.values(state.assumptions).every(Boolean),meets=result.cpk!==null&&result.cpk>=state.minCpk;return hero('CAPACIDADE & DESEMPENHO','A tolerância encontra <em>a realidade.</em>','Compare a voz do processo com a voz do cliente. Estabilidade, normalidade e uma medição adequada dão contexto aos índices.')+toolbar()+`<div class="two-col"><div><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Distribuição × especificação</h2><p class="panel-sub">${escape(state.process)} · ${result.count} medições individuais</p></div><span class="pill ${ready?'':'amber'}">${ready?'Premissas declaradas':'Leitura condicional'}</span></div><div class="panel-body">${histogram()}<div class="section-row"><span class="help-text">LI <strong>${fmt(state.lsl,3)}</strong> · Alvo <strong>${fmt(state.target,3)}</strong> · LS <strong>${fmt(state.usl,3)}</strong></span><span class="pill ${result.oos?'red':''}">${result.oos} fora da especificação</span></div><p class="chart-caption">O histograma mostra a distribuição; a carta preserva a ordem temporal. A forma visual não comprova normalidade.</p></div></section><section class="panel mt"><div class="panel-head"><h2 class="panel-title">Dois olhares para a variação</h2></div><div class="panel-body"><div class="stat-list">${[['Cp',result.cp,'Potencial · σ̂ dentro'],['Cpk',result.cpk,'Centralização + σ̂ dentro'],['Pp',result.pp,'Largura · desvio global s'],['Ppk',result.ppk,'Centralização + desvio global s']].map(([k,v,l])=>`<div class="stat-box"><span>${k}</span><strong>${fmt(v,3)}</strong><small>${l}</small></div>`).join('')}</div><div class="notice ${!ready?'amber':''}"><strong>${result.events.length?'Há sinais especiais: capacidade não demonstrada.':result.zero?'Variação zero: índices indisponíveis.':result.short?'Base preliminar: amplie a coleta.':ready?(meets?'A estimativa de Cpk atende à meta configurada.':'A estimativa de Cpk está abaixo da meta configurada.'):'Os índices são estimativas condicionais.'}</strong><br>${result.events.length?'Valores exibidos para aprendizagem; não use os índices como evidência de um processo previsível.':!ready?'Confirme as premissas ao lado. Ausência de sinais e índices altos não substituem a validação técnica.':'As premissas foram declaradas por você. Não há teste automático de normalidade, MSA ou aprovação de cliente.'}</div><p class="help-text">Média: ${fmt(result.mean,4)} ${escape(state.unit)} · σ̂ dentro: ${fmt(result.within,5)} · s global (n−1): ${fmt(result.s,5)}. ${result.zero?'A resolução pode ser insuficiente para detectar a variação.':'Cp e Cpk usam '+(state.mode==='imr'?'MR̄ / 1,128':'R̄ / d₂')+'; Pp e Ppk usam o desvio padrão amostral de todas as leituras.'}</p></div></section></div><aside><section class="panel"><div class="panel-head"><h2 class="panel-title">Checklist de interpretação</h2></div><div class="panel-body"><span class="pill ${st.class==='good'?'':st.class==='bad'?'red':'amber'}">${st.short}</span><div class="checklist">${[['msa','Medição adequada','MSA e resolução avaliadas para esta característica.'],['rational','Coleta representativa','Independência e subgrupos racionais verificados.'],['normal','Modelo normal justificável','Forma, contexto e análise de distribuição avaliados fora do simulador.']].map(([id,t,h])=>`<label><input type="checkbox" data-assumption="${id}" ${state.assumptions[id]?'checked':''}><span>${t}<small>${h}</small></span></label>`).join('')}</div><p class="help-text">As marcações são declarações, não testes. Para dados não normais ou autocorrelacionados, use um método apropriado e evite interpretar estes índices diretamente.</p><div class="section-row mt"><strong style="font-size:11px">Cpk × meta didática</strong><span style="font-size:10px">≥ ${fmt(state.minCpk,2)}</span></div><div class="meter" role="img" aria-label="Cpk ${fmt(result.cpk,2)}; escala de 0 a 2"><i style="left:${Math.min(100,Math.max(0,(result.cpk||0)/2*100))}%"></i></div><div class="meter-labels"><span>0</span><span>1,00</span><span>2,00</span></div><p class="help-text">A meta de ${fmt(state.minCpk,2)} é configurável e não representa um requisito universal. Verifique CSR, fase do processo e acordo com o cliente.</p></div></section><section class="panel mt"><div class="panel-head"><h2 class="panel-title">Conformidade observada</h2></div><div class="panel-body"><div class="kpi-value ${result.oos?'warn':'good'}">${fmt(100*(1-result.oos/result.count),1)}<small>% na amostra</small></div><p class="help-text">${result.oos} de ${result.count} leituras fora de LI/LS.<br>${fmt(result.ppmObserved,0)} ppm observados nesta amostra.</p><div class="notice">Conformidade amostral não é previsão de refugo futuro. Nenhuma conversão automática de Cpk para ppm é feita.</div></div></section></aside></div>`;}
const EXERCISES=[
 {title:'Controle ou especificação?',topic:'Fundamento',context:'Uma carta mostra todos os pontos entre LIC e LSC. Duas peças ultrapassaram o limite superior de especificação do desenho.',question:'Qual conclusão respeita a diferença entre estabilidade e conformidade?',options:['O processo é capaz, pois nenhum ponto cruzou os limites de controle.','As duas peças são não conformes; a estabilidade exige avaliar regras e dispersão.','É preciso ampliar o LS do desenho para incluir as peças.'],correct:1,explanation:'Limites de controle descrevem o comportamento estatístico; especificação define o requisito. Trate as peças fora de especificação e avalie também dispersão e padrões. Mesmo um processo estável pode produzir não conformidades.',hint:'Quem define cada limite: o processo ou o cliente?',action:'Confirme a disposição do produto e revise a capacidade frente à tolerância.'},
 {title:'A troca de ferramenta',topic:'Causa especial',scenario:'shift',context:'Na Amazônia Precisão, a ferramenta foi substituída durante a coleta. Após a troca, as médias mudaram de patamar, mas a tolerância continua ampla.',question:'O Cpk alto permite declarar o processo estável?',options:['Sim. Cpk acima da meta substitui a análise da carta.','Sim, desde que nenhuma peça esteja fora da especificação.','Não. Investigue a mudança, valide o setup e registre a reação.'],correct:2,explanation:'A mudança de patamar é um sinal temporal de causa especial. O índice calculado com uma base que mistura condições não demonstra previsibilidade. Valide a correção e reúna uma base representativa antes de estabelecer novos limites.',hint:'Observe a sequência temporal, não apenas o número do Cpk.',action:'Verifique offset, preset da ferramenta, primeira peça e último ponto conhecido conforme.'},
 {title:'Calcule o Cpk',topic:'Cálculo',numeric:true,context:'Uma característica tem LI = 49,90 mm; LS = 50,10 mm; média = 50,02 mm; σ̂ dentro = 0,020 mm.',question:'Qual é o Cpk? Digite com duas ou três casas decimais.',answer:1.3333333333,tolerance:.01,explanation:'Cpl = (50,02 − 49,90) / (3 × 0,020) = 2,00. Cpu = (50,10 − 50,02) / (3 × 0,020) = 1,333. Cpk é o menor dos dois: 1,333. Cp = 0,20 / 0,12 = 1,667; a diferença evidencia a descentralização.',hint:'Cpk = mínimo entre (LS − média)/(3σ̂) e (média − LI)/(3σ̂).',action:'Avalie centralização; o lado superior da especificação é o mais crítico.'},
 {title:'Estável não basta',topic:'Capacidade',scenario:'incapable',context:'As cartas não sinalizam causas especiais nas regras ativas. A tolerância é estreita e o Cpk está abaixo da meta acordada.',question:'Qual ação é mais adequada?',options:['Ajustar a máquina após cada oscilação de uma peça.','Reduzir a variação do sistema e avaliar contenção conforme o risco do produto.','Apagar os valores extremos até obter Cpk maior que a meta.'],correct:1,explanation:'Variação comum exige melhorar o sistema: equipamento, método, material e medição. Ajustes frequentes sem causa comprovada podem aumentar a variação. Não exclua dados para melhorar um índice; registre critérios técnicos e mantenha rastreabilidade.',hint:'Uma causa comum pede melhoria do sistema, não reação a toda oscilação.',action:'Priorize fontes de dispersão e atualize o Plano de Controle após validar a melhoria.'},
 {title:'Cp, Cpk, Pp ou Ppk?',topic:'Interpretação',scenario:'offcenter',context:'O processo tem baixa dispersão dentro dos subgrupos, mas a média está próxima do LS. Cp é alto e Cpk é menor.',question:'O que a diferença entre Cp e Cpk indica?',options:['A média está deslocada em relação ao centro da especificação.','O instrumento está aprovado automaticamente.','Ppk é sempre maior que Cpk.'],correct:0,explanation:'Cp usa apenas a largura da especificação e a variação dentro. Cpk também considera a distância da média ao limite mais próximo. Pp/Ppk usam a variação global e não têm uma ordem universal em relação a Cp/Cpk.',hint:'Compare o espaço disponível nos dois lados da média.',action:'Planeje o ajuste do offset e verifique se a centralização foi sustentada sem elevar a dispersão.'},
 {title:'Do sinal ao Plano de Controle',topic:'Aplicação industrial',scenario:'variation',context:'Um subgrupo teve amplitude muito maior após uma intervenção na fixação. A carta de médias, isoladamente, parece pouco alterada.',question:'Qual sequência fecha o ciclo de controle?',options:['Liberar a produção com base na média e ignorar a carta R.','Recalcular os limites incluindo o evento para eliminar o sinal.','Proteger o produto, investigar a fixação, validar a ação e atualizar os controles.'],correct:2,explanation:'Comece pela dispersão. Contenha conforme o risco e o plano de reação, investigue 6M, registre causa e ação, valide a eficácia. Leve o aprendizado ao PFMEA, Plano de Controle e evidências de aprovação quando aplicável.',hint:'Uma média aceitável pode esconder diferenças grandes entre as peças.',action:'Defina responsável, prazo, rastreabilidade do produto e critério de retorno à condição normal.'}
];
function exercisesPage(){const i=Math.min(5,Math.max(0,state.exercise)),e=EXERCISES[i],done=Object.values(state.done).filter(Boolean).length;return hero('PRÁTICA GUIADA','Treine o olhar. <em>Melhore a decisão.</em>','Seis desafios curtos para conectar cálculo, interpretação e reação no chão de fábrica. Tente, receba feedback e evolua.')+`<div class="exercise-layout"><nav class="exercise-nav" aria-label="Lista de exercícios">${EXERCISES.map((x,j)=>`<button class="exercise-item ${j===i?'active':''}" data-exercise="${j}" ${j===i?'aria-current="step"':''}><span class="exercise-no">${state.done[j]?'✓':String(j+1).padStart(2,'0')}</span><span><strong>${x.title}</strong><small>${x.topic} ${state.done[j]?'· Concluído':''}</small></span></button>`).join('')}</nav><section class="panel exercise-content"><div class="section-row"><span class="eyebrow" style="color:#89a16f">MISSÃO ${String(i+1).padStart(2,'0')} / 06</span><span class="pill">${done} de 6 concluídas</span></div><h2>${e.title}</h2><p>Contexto industrial · ${e.topic}</p><div class="exercise-context">${e.context}</div>${e.scenario?`<button class="btn small" data-load-exercise="${e.scenario}">${icon('chart')} Explorar cenário no laboratório ${icon('arrow')}</button>`:''}<form id="exerciseForm"><p style="color:#405e35;margin-top:24px"><strong>${e.question}</strong></p>${e.numeric?`<div class="field" style="max-width:240px"><label for="numericAnswer">Seu Cpk calculado</label><input id="numericAnswer" name="answer" inputmode="decimal" placeholder="Ex.: 1,234" value="${escape(exerciseAnswer)}" required autocomplete="off"></div>`:`<div class="options">${e.options.map((o,j)=>`<label class="option"><input type="radio" name="answer" value="${j}" required ${String(feedback?.selected??exerciseAnswer)===String(j)?'checked':''}><span>${o}</span></label>`).join('')}</div>`}<div class="form-actions"><button type="submit" class="btn primary">Verificar resposta ${icon('check')}</button><button type="button" class="btn ghost" data-action="hint">${icon('bulb')} Uma dica</button></div></form>${hint?`<div class="hint">${e.hint}</div>`:''}${feedback?`<div class="feedback ${feedback.correct?'':'incorrect'}" role="status"><strong>${feedback.correct?'Boa leitura. Decisão sustentada por evidências.':'Vamos ajustar o raciocínio.'}</strong><p>${e.explanation}</p><p><strong>Na prática:</strong> ${e.action}</p></div><div class="form-actions"><button class="btn" data-next-exercise="${(i+1)%6}">${i===5?'Voltar à primeira missão':'Próxima missão'} ${icon('arrow')}</button></div>`:''}<p class="help-text mt">Seu progresso fica neste navegador e acompanha o backup da análise. Tentativas são livres; conclusão não equivale a certificação.</p></section></div>`;}
function guidePage(){return hero('GUIA DE DECISÃO','O índice informa. <em>O contexto decide.</em>','Um roteiro de aplicação para conectar medição, variação, risco e resposta industrial.')+`<div class="notice">Este laboratório é autoral e independente, inspirado na trilha de Especialista em Core Tools e no conteúdo disponível do Core Tools Lab Deko. Não reproduz o curso integral nem confere certificação AIAG, VDA ou IQA.</div><div class="guide-grid mt"><section class="panel guide-card"><span class="number-label">01 / ESCOLHER E COLETAR</span><h2>A carta começa no plano de coleta.</h2><p><strong>I–MR:</strong> uma medição por intervalo ou lote, quando um subgrupo não é viável. MR usa pares consecutivos; a primeira leitura não tem amplitude móvel.</p><p><strong>X̄–R:</strong> subgrupos racionais de 2 a 10 peças coletadas em condições próximas. Uma linha por subgrupo, em ordem cronológica.</p><p>Avalie resolução, MSA, independência e representatividade. Para autocorrelação, dados por atributos, subgrupos maiores ou modelos não normais, use ferramentas específicas; estas situações não estão cobertas pelo motor.</p></section><section class="panel guide-card"><span class="number-label">02 / ENTENDER O COMPORTAMENTO</span><h2>Primeiro a dispersão, depois a localização.</h2><p>Inspecione R ou MR antes de concluir sobre X̄ ou I. Um sinal indica investigação, não revela automaticamente a causa. Nove pontos do mesmo lado e seis em tendência são regras de padrão; as regras de zona são opcionais.</p><p>As janelas sobrepostas geram várias ocorrências. Um ponto pode aparecer em mais de um sinal. Empates interrompem a tendência; pontos na linha central interrompem a regra de mesmo lado.</p><p>O simulador faz <strong>Fase I</strong>: estima limites com a base atual, sem exclusão automática. Menos de 20 pontos/subgrupos gera alerta de base curta. Ausência de sinais não comprova estabilidade definitiva.</p></section><section class="panel guide-card"><span class="number-label">03 / FÓRMULAS DE CONTROLE</span><h2>O cálculo, sem caixa-preta.</h2><div class="formula">I: LC = média; limites = média ± 3 × MR̄ / 1,128<br>MR: LC = MR̄; LIC = 0; LSC = 3,267 × MR̄</div><div class="formula">X̄: LC = média geral; limites = LC ± A₂ × R̄<br>R: LC = R̄; LIC = D₃ × R̄; LSC = D₄ × R̄</div><p>R̄ é a média das amplitudes dos subgrupos. MR̄ é a média das diferenças absolutas entre observações consecutivas. As regras de zona usam 1/3 da distância entre LC e LSC na carta de localização.</p><details><summary class="text-link">Ver tabela de constantes</summary><div class="table-scroll mt"><table class="data-table"><thead><tr><th>n</th><th>d₂</th><th>A₂</th><th>D₃</th><th>D₄</th></tr></thead><tbody>${Object.entries(CONSTANTS).map(([n,c])=>`<tr><td>${n}</td><td>${fmt(c.d2)}</td><td>${fmt(c.A2)}</td><td>${fmt(c.D3)}</td><td>${fmt(c.D4)}</td></tr>`).join('')}</tbody></table></div></details><p>Constantes tabeladas com três casas decimais; pequenas diferenças de arredondamento são esperadas. Nenhum limite de especificação entra no cálculo dos limites de controle.</p></section><section class="panel guide-card"><span class="number-label">04 / COMPARAR COM O REQUISITO</span><h2>Capacidade exige premissas.</h2><div class="formula">Cp = (LS − LI) / (6σ̂ dentro)<br>Cpk = mín[(LS − média)/(3σ̂), (média − LI)/(3σ̂)]<br>Pp e Ppk: mesmas expressões, usando s global.</div><p><strong>σ̂ dentro:</strong> R̄/d₂ em X̄–R; MR̄/1,128 em I–MR. <strong>s global:</strong> desvio padrão amostral de todas as leituras, com divisor N−1.</p><p>O motor mantém Cpk negativo quando a média está além da especificação. Variação zero deixa os índices indisponíveis. Somente especificações bilaterais são aceitas.</p><p>Normalidade, independência e adequação do sistema de medição não são testadas automaticamente. Com causas especiais, os números são exploratórios. A meta padrão 1,33 é didática, ajustável e deve ser confrontada com requisitos do cliente.</p></section><section class="panel guide-card"><span class="number-label">05 / FECHAR O CICLO INDUSTRIAL</span><h2>O sinal precisa virar uma ação.</h2><ol class="steps"><li><div><strong>Proteja o produto</strong>Aplique o plano de reação e determine a janela afetada pelo risco.</div></li><li><div><strong>Investigue e registre</strong>Compare método, máquina, material, mão de obra, medição e meio ambiente.</div></li><li><div><strong>Valide a eficácia</strong>Reúna dados após a ação e justifique a revisão de limites.</div></li><li><div><strong>Conecte as Core Tools</strong>Atualize o PFMEA, Plano de Controle e as evidências APQP/PPAP pertinentes.</div></li></ol><p>Evite ajustar o processo por cada oscilação de causa comum. A ação deve ser proporcional ao sinal e ao risco.</p></section><section class="panel guide-card"><span class="number-label">06 / REFERÊNCIAS & ESCOPO</span><h2>Fundamentação e transparência.</h2><p>Os métodos clássicos foram conferidos com o NIST/SEMATECH e contextualizados pelas informações públicas de AIAG & VDA. O manual integral licenciado e a apostila integral do curso não foram consultados.</p><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://www.itl.nist.gov/div898/handbook/pmc/section3/pmc312.htm">NIST · Cartas de valores individuais ↗</a><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://www.itl.nist.gov/div898/handbook/pmc/section3/pmc321.htm">NIST · Cartas X̄, R e S ↗</a><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://www.itl.nist.gov/div898/handbook/pmc/section1/pmc16.htm">NIST · Capacidade de processo ↗</a><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://www.itl.nist.gov/div898/handbook/pmc/section1/pmc14.htm">NIST · Reação e regras de sinalização ↗</a><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://www.aiag.org/training-and-resources/manuals/details/SPCAV-1">AIAG · Manual harmonizado AIAG & VDA SPC ↗</a><p>Os dados de treinamento são sintéticos. Medições e progresso ficam neste navegador; o backup JSON permite transferência. A hospedagem privada controla acesso à página, mas não sincroniza dados entre dispositivos.</p></section></div>`;}
function render(){document.getElementById('app').innerHTML=shell(({process:processPage,data:dataPage,capability:capabilityPage,exercises:exercisesPage,guide:guidePage}[view])());}
function download(name,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Arquivo preparado para download.');}
function backup(){download('spc-lab-backup.json',JSON.stringify({kind:'spc-lab-backup',version:1,state},null,2),'application/json');}
function csv(){download('spc-lab-medicoes.csv','\uFEFF'+(state.mode==='xbar'?Array.from({length:result.n},(_,i)=>'x'+(i+1)).join(';'):'valor')+'\n'+result.groups.map(g=>g.map(x=>String(x).replace('.',',')).join(';')).join('\n'),'text/csv;charset=utf-8');}
function report(){
 const st=status(),now=new Date().toLocaleString('pt-BR',{timeZone:'America/Manaus'});
 const text=[
 '# SPC Lab · Análise de processo','',state.process+' · '+state.unit,
 'Gerado em '+now+' (Manaus)',state.custom?'Base inserida pelo usuário':'Cenário sintético: '+scenario().name,'',
 '## Leitura do processo','',st.short+' · '+st.text,
 'Fase I: limites estimados com a base atual, sem exclusão automática.',
 result.events.length?'Capacidade não demonstrada; índices exploratórios.':'Índices condicionados à estabilidade, normalidade, independência e medição adequada.','',
 '## Configuração e resultados','',
 '| Indicador | Resultado |','| --- | --- |',
 '| Carta | '+(state.mode==='imr'?'I–MR':'X̄–R')+' |',
 '| Medições / pontos ou subgrupos | '+result.count+' / '+result.points+' |',
 '| LI / Alvo / LS | '+[state.lsl,state.target,state.usl].map(x=>fmt(x,4)).join(' / ')+' |',
 '| Média / σ̂ dentro / s global | '+[result.mean,result.within,result.s].map(x=>fmt(x,5)).join(' / ')+' |',
 '| Cp / Cpk / Pp / Ppk | '+[result.cp,result.cpk,result.pp,result.ppk].map(x=>fmt(x,4)).join(' / ')+' |',
 '| Meta didática Cpk | '+fmt(state.minCpk,2)+' |',
 '| Localização LIC / LC / LSC | '+[result.limits.lcl,result.limits.cl,result.limits.ucl].map(x=>fmt(x,5)).join(' / ')+' |',
 '| Dispersão LIC / LC / LSC | '+[result.rangeLimits.lcl,result.rangeLimits.cl,result.rangeLimits.ucl].map(x=>fmt(x,5)).join(' / ')+' |',
 '| Não conformes na amostra | '+result.oos+' de '+result.count+' ('+fmt(result.ppmObserved,0)+' ppm observados) |','',
 'Regras de localização: '+state.rules.map(r=>({r1:'Além de 3σ',r2:'9 do mesmo lado',r3:'6 em tendência',r4:'2 de 3 além de 2σ',r5:'4 de 5 além de 1σ'}[r])).join('; ')+'. Dispersão: ponto fora dos limites.','',
 'Premissas declaradas: '+[['msa','Medição'],['rational','Coleta'],['normal','Modelo normal']].map(([k,v])=>v+': '+(state.assumptions[k]?'verificada pelo usuário':'não declarada')).join('; ')+'.','',
 '## Sinais','',...(result.events.length?result.events.map(e=>'- '+e.chart+' · '+(e.start+1)+'–'+(e.end+1)+': '+e.text):['Nenhum sinal nas regras ativas. Ausência de sinais não comprova estabilidade definitiva.']),'',
 '## Medições em ordem de coleta','', '| Ponto / grupo | Leituras |','| --- | --- |',...result.groups.map((g,i)=>'| '+(i+1)+' | '+g.map(x=>fmt(x,4)).join(' ; ')+' |'),'','## Método e limitações','',
 'σ̂ dentro = '+(state.mode==='imr'?'MR̄ / 1,128':'R̄ / d₂')+'; s global usa N−1. Cp = (LS−LI)/(6σ̂); Cpk = mín[(LS−média)/(3σ̂), (média−LI)/(3σ̂)]. Pp/Ppk substituem σ̂ por s global. Constantes com três casas decimais.',
 'Não há teste automático de normalidade, MSA ou autocorrelação. Dados não normais exigem métodos específicos. Menos de 20 pontos/subgrupos gera alerta de base curta.','',
 'Fundamentação: https://www.itl.nist.gov/div898/handbook/pmc/pmc.htm',
 'Ambiente autoral independente; não confere certificação AIAG, VDA ou IQA.'
 ].join('\n');download('spc-lab-relatorio.md',text,'text/markdown;charset=utf-8');
}
function submitData(form){const f=new FormData(form);try{const draft={...state,process:String(f.get('process')).trim(),unit:String(f.get('unit')).trim(),raw:String(f.get('raw')),mode:f.get('mode'),n:+f.get('n'),lsl:number(f.get('lsl')),usl:number(f.get('usl')),target:number(f.get('target')),minCpk:number(f.get('minCpk')),delimiter:f.get('delimiter'),rules:f.getAll('rules'),custom:true,assumptions:{msa:false,rational:false,normal:false}};if(!draft.process||!draft.unit)throw new Error('Informe o nome do processo e a unidade.');if(!(draft.minCpk>0)||draft.minCpk>10)throw new Error('A meta de Cpk deve ser maior que zero e até 10.');if(draft.rules.length===0)throw new Error('Ative pelo menos uma regra para a carta de localização.');const g=parseData(draft.raw,draft.mode,draft.n,draft.delimiter);const r=analyze(g,draft);state=draft;result=r;save();selectedPoint=null;chartTab='primary';formError='';navigate('process');toast('Análise atualizada com a sua base.');}catch(e){let error=form.querySelector('.notice.error');if(!error){error=document.createElement('div');error.className='notice error';error.setAttribute('role','alert');form.prepend(error);}error.textContent=e.message;error.scrollIntoView({behavior:'smooth',block:'center'});}}
async function importFile(file){if(!file)return;if(file.size>1e6){toast('Arquivo muito grande. Use até 1 MB.');return;}try{const txt=await file.text();if(file.name.toLowerCase().endsWith('.json')){const data=JSON.parse(txt);if(data.kind!=='spc-lab-backup'||data.version!==1||!data.state)throw new Error('Backup incompatível. Use um arquivo exportado pelo SPC Lab.');const s=data.state;analyze(parseData(s.raw,s.mode,s.n,s.delimiter||'auto'),s);if(!(s.minCpk>0&&s.minCpk<=10)||!Array.isArray(s.rules)||!s.rules.length||s.rules.some(r=>!['r1','r2','r3','r4','r5'].includes(r)))throw new Error('Configuração do backup inválida.');for(const k of ['process','unit'])if(typeof s[k]!=='string'||s[k].length>120||!s[k])throw new Error('Metadados inválidos no backup.');const clean={...state,...s,assumptions:{msa:!!s.assumptions?.msa,rational:!!s.assumptions?.rational,normal:!!s.assumptions?.normal},done:Object.fromEntries(Object.entries(s.done||{}).filter(([k,v])=>/^[0-5]$/.test(k)&&v===true)),exercise:Number.isInteger(s.exercise)?Math.min(5,Math.max(0,s.exercise)):0};state=clean;calculate();save();selectedPoint=null;render();toast('Backup restaurado: base, configuração e progresso.');}else{document.getElementById('rawData').value=txt.replace(/^\uFEFF/,'');toast('Arquivo no editor. Confira a carta e o separador, depois calcule.');}}catch(e){toast(e.message||'Não foi possível ler o arquivo.');}}
document.addEventListener('click',e=>{const route=e.target.closest('[data-route]');if(route){e.preventDefault();navigate(route.dataset.route);return;}const a=e.target.closest('[data-action]');if(a){const act=a.dataset.action;if(act==='menu'){mobile=!mobile;document.querySelector('.app-shell').classList.toggle('menu-open',mobile);document.querySelector('.mobile-menu')?.setAttribute('aria-expanded',mobile);return;}if(act==='csv')csv();if(act==='backup')backup();if(act==='report')report();if(act==='clearPoint'){selectedPoint=null;render();}if(act==='hint'){exerciseAnswer=document.getElementById('numericAnswer')?.value??document.querySelector('input[name="answer"]:checked')?.value??'';hint=!hint;render();}return;}const tab=e.target.closest('[data-tab]');if(tab){chartTab=tab.dataset.tab;selectedPoint=null;render();return;}const pt=e.target.closest('[data-point]');if(pt){selectedPoint=+pt.dataset.point;render();return;}const eventPt=e.target.closest('[data-event-point]');if(eventPt){selectedPoint=+eventPt.dataset.eventPoint;chartTab=['I','X̄'].includes(eventPt.dataset.eventChart)?'primary':'secondary';chartWindow=0;render();document.querySelector('.chart-area')?.scrollIntoView({behavior:'smooth',block:'center'});return;}const ex=e.target.closest('[data-exercise],[data-next-exercise]');if(ex){state.exercise=+(ex.dataset.exercise??ex.dataset.nextExercise);feedback=null;hint=false;exerciseAnswer='';save();render();return;}const load=e.target.closest('[data-load-exercise]');if(load){loadScenario(load.dataset.loadExercise);navigate('process');}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-point]')){e.preventDefault();selectedPoint=+e.target.dataset.point;render();}if(e.key==='Escape'&&mobile){mobile=false;document.querySelector('.app-shell').classList.remove('menu-open');document.querySelector('.mobile-menu')?.setAttribute('aria-expanded',false);}});
document.addEventListener('change',e=>{if(e.target.id==='scenario'&&e.target.value!=='custom')loadScenario(e.target.value);if(e.target.id==='quickMode'){if(state.custom){toast('Para alterar a carta da sua base, use Dados & coleta e confirme o formato.');navigate('data');document.getElementById('draftMode').value=e.target.value;}else loadScenario(state.scenario,e.target.value);}if(e.target.id==='chartWindow'){chartWindow=+e.target.value;render();}if(e.target.id==='fileInput')importFile(e.target.files[0]);if(e.target.matches('[data-assumption]')){state.assumptions[e.target.dataset.assumption]=e.target.checked;save();render();}});
document.addEventListener('submit',e=>{if(e.target.id==='dataForm'){e.preventDefault();submitData(e.target);}if(e.target.id==='exerciseForm'){e.preventDefault();const ex=EXERCISES[state.exercise],value=new FormData(e.target).get('answer');const selected=number(value);if(!Number.isFinite(selected)){toast('Digite uma resposta numérica válida.');return;}const correct=ex.numeric?Math.abs(selected-ex.answer)<=ex.tolerance:selected===ex.correct;exerciseAnswer=String(value);feedback={correct,selected};if(correct){state.done[state.exercise]=true;save();}render();document.querySelector('.feedback')?.scrollIntoView({behavior:'smooth',block:'nearest'});}});
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){document.getElementById('main')?.scrollIntoView();return;}navigate(location.hash.slice(1));});
render();
